import factory = require( './index' );
import BigInt = require( '@stdlib/bigint/ctor' );
 
// TESTS //
 
// The function returns a generator...
{
	factory(); // $ExpectType NullaryFunction
}
 
// The compiler throws an error if the function is provided any arguments...
{
	factory( true ); // $ExpectError
	factory( 2, 3 ); // $ExpectError
}
 
// The returned generator returns a bigint...
{
	const rng = factory();
	rng(); // $ExpectType bigint
}
 
// The compiler throws an error if the generator is provided any arguments...
{
	const rng = factory();
	rng( true ); // $ExpectError
	rng( 123 ); // $ExpectError
	rng( 'abc' ); // $ExpectError
}
 
// Attached to returned generator is a `normalized` method which returns a number...
{
	const rng = factory();
	rng.normalized(); // $ExpectType number
}
 
// The compiler throws an error if the `normalized` method is provided any arguments...
{
	const rng = factory();
	rng.normalized( true ); // $ExpectError
	rng.normalized( 123 ); // $ExpectError
	rng.normalized( 'abc' ); // $ExpectError
}
 
// Attached to returned generator is a `copy` method which returns a generator...
{
	const rng = factory();
	rng.copy(); // $ExpectType NullaryFunction
}
 
// The compiler throws an error if the `copy` method is provided any arguments...
{
	const rng = factory();
	rng.copy( true ); // $ExpectError
	rng.copy( 123 ); // $ExpectError
}
 
// Attached to returned generator is a `toJSON` method which returns a object...
{
	const rng = factory();
	rng.toJSON(); // $ExpectType object
}
 
// The compiler throws an error if the `toJSON` method is provided any arguments...
{
	const rng = factory();
	rng.toJSON( true ); // $ExpectError
	rng.toJSON( 123 ); // $ExpectError
}
 
// The compiler throws an error if the `factory` function is provided an options argument which is not an object...
{
	factory( null ); // $ExpectError
	factory( 'abc' ); // $ExpectError
	factory( 123 ); // $ExpectError
}
 
// The compiler throws an error if the `factory` function is provided a `seed` option which is not a valid seed...
{
	factory( { 'seed': true } ); // $ExpectError
	factory( { 'seed': 'abc' } ); // $ExpectError
	factory( { 'seed': null } ); // $ExpectError
	factory( { 'seed': [] } ); // $ExpectError
	factory( { 'seed': {} } ); // $ExpectError
	factory( { 'seed': ( x: number ): number => x } ); // $ExpectError
}
 
// The compiler throws an error if the `factory` function is provided a `state` option which is not a valid state...
{
	factory( { 'state': 123 } ); // $ExpectError
	factory( { 'state': 'abc' } ); // $ExpectError
	factory( { 'state': null } ); // $ExpectError
	factory( { 'state': {} } ); // $ExpectError
	factory( { 'state': true } ); // $ExpectError
	factory( { 'state': ( x: number ): number => x } ); // $ExpectError
}
 
// The compiler throws an error if the `factory` function is provided a `copy` option which is not a boolean...
{
	factory( { 'copy': 123 } ); // $ExpectError
	factory( { 'copy': 'abc' } ); // $ExpectError
	factory( { 'copy': null } ); // $ExpectError
	factory( { 'copy': [] } ); // $ExpectError
	factory( { 'copy': {} } ); // $ExpectError
	factory( { 'copy': ( x: number ): number => x } ); // $ExpectError
}
 
// The compiler throws an error if the `factory` function is provided more than one argument...
{
	factory( {}, 2 ); // $ExpectError
}
 
// Valid usage...
{
	const rng = factory( { 'seed': BigInt( 1234 ) } );
	const v1 = rng();
	const v2 = rng.normalized();
	const state = rng.state;
	rng.state = state;
	const copy = rng.copy();
	const json = rng.toJSON();
}
 